def esc(s):
    return str(s).replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace('"',"&quot;")

class Cover(Flowable):
    def __init__(self,title,subtitle,back=False,accent="#8E7CFF",num=1,domain=""):
        super().__init__()
        self.width=LETTER[0]; self.height=LETTER[1]
        self.title=title; self.subtitle=subtitle; self.back=back; self.accent=accent; self.num=num; self.domain=domain
    def wrap(self,w,h):
        self.width=w
        self.height=h
        return w,h
    def draw(self):
        c=self.canv; W,H=self.width,self.height
        c.setFillColor(colors.HexColor("#070707")); c.rect(0,0,W,H,fill=1,stroke=0)
        c.setFillColor(colors.HexColor(self.accent)); c.rect(0,0,9,H,fill=1,stroke=0)
        c.setStrokeColor(colors.HexColor("#303030"))
        for i in range(10): c.line(52,170+i*55,W-52,170+i*55)
        c.setFillColor(colors.white); c.setFont("Helvetica",6.8)
        c.drawString(52,H-44,"DEWIFY / EBOOX 100")
        c.drawRightString(W-52,H-44,f"{self.num:02d} / 100")
        if not self.back:
            c.setFont("Helvetica-Bold",31)
            y=H*0.58
            for j,line in enumerate(self.title.split(" | ")):
                c.drawString(52,y-j*38,line[:34])
            c.setFillColor(colors.HexColor("#BDBDBD")); c.setFont("Helvetica",7.2)
            c.drawString(52,y-88,self.domain.upper())
            c.setFont("Helvetica",7.2)
            c.drawString(52,80,"100 BOOKS. ONE PRIVATE LIBRARY.")
        else:
            c.setFillColor(colors.white); c.setFont("Helvetica-Bold",16)
            c.drawString(52,H-110,self.title)
            c.setFillColor(colors.HexColor("#BDBDBD")); c.setFont("Helvetica",8.3)
            y=H-145
            for para in self.subtitle.split("\\n"):
                for chunk in [para[i:i+88] for i in range(0,len(para),88)]:
                    c.drawString(52,y,chunk); y-=14
                y-=5
            c.setFillColor(colors.HexColor(self.accent)); c.setFont("Helvetica",6.8)
            c.drawString(52,44,"EBOOX 100 / DIGITAL LIBRARY")

def para(text,style=body):
    return Paragraph(esc(text),style)

def normal_page(canvas,doc):
    W,H=LETTER
    if doc.page==1:
        canvas.saveState()
        canvas.setFillColor(colors.HexColor("#070707"))
        canvas.rect(0,0,W,H,fill=1,stroke=0)
        canvas.restoreState()
    else:
        canvas.saveState()
        canvas.setStrokeColor(colors.HexColor("#D9D9D9"))
        canvas.line(52,40,W-52,40)
        canvas.setFillColor(colors.HexColor("#777777"))
        canvas.setFont("Helvetica",6.8)
        canvas.drawString(52,26,"EBOOX 100 / PRIVATE DIGITAL LIBRARY")
        canvas.drawRightString(W-52,26,str(doc.page))
        canvas.restoreState()

def back_page(canvas,doc):
    W,H=LETTER
    canvas.saveState()
    canvas.setFillColor(colors.HexColor("#070707"))
    canvas.rect(0,0,W,H,fill=1,stroke=0)
    canvas.restoreState()

def chapter_copy(row,chapter,index):
    title=row["title"]; domain=row["domain"]
    lens=chapter
    return [
        f"{lens} is the practical angle for this part of {title}. The point is not to collect another concept. It is to make one recurring decision easier to see, discuss, test, and improve.",
        f"For a reader working on {title.lower()}, start by separating the desired outcome from the current method. The same method can look efficient while hiding an expensive trade-off. Write down what must remain true, what can change, and what evidence would make you update the approach.",
        f"A useful application is to take one real situation from the last seven days and run the {domain.lower()} lens over it. Notice the trigger, the constraint, the action, and the review point. The aim is to build a small operating rule rather than a large theory.",
        "The edge case matters too. A framework becomes more trustworthy when you know when not to use it. If the stakes are high, the information is weak, or the downside is difficult to reverse, add a slower review step instead of pretending speed is always a virtue.",
        f"Chapter action: document one example of {lens.lower()} in your own work. Then write one sentence beginning with 'I will do this differently when...' and make the trigger specific enough that another person could recognize it."
    ]

def build_book(row,num):
    domain=row["domain"]; title=row["title"]; accent=PALETTES[domain]
    slug=re.sub(r"[^a-z0-9]+","-",title.lower()).strip("-")
    path=os.path.join(BOOKS,f"{num:02d}-{slug}.pdf")
    doc=BaseDocTemplate(path,pagesize=LETTER,leftMargin=52,rightMargin=52,topMargin=56,bottomMargin=54,title=title,author="EBOOX 100 Editorial Library")
    frame=Frame(doc.leftMargin,doc.bottomMargin,doc.width,doc.height,id="normal",showBoundary=0)
    doc.addPageTemplates([PageTemplate(id="normal",frames=[frame],onPage=normal_page),PageTemplate(id="back",frames=[frame],onPage=back_page)])
    story=[Cover(title,f"{row['thesis']}\\n\\n{row['problem']}",False,accent,num,domain),PageBreak()]
    story += [para("EBOOX 100",h1),para(title,ParagraphStyle("BookTitle",parent=h2,fontSize=17,leading=21,textColor=colors.HexColor(accent))),
              para(f"Book {num:02d} of 100",small),para("Independent digital edition for the EBOOX 100 library.",small),Spacer(1,18),
              para("ORIGINALITY & EDITORIAL NOTE",h2),
              para("This book was independently written for EBOOX 100. It does not reproduce passages, distinctive wording, chapter structures, signature frameworks, cover designs, or author-specific styles from other books.",small),
              PageBreak()]
    story += [para("Reader Brief",h1),para("Central thesis: "+row["thesis"]),para("Target reader: "+row["reader"]),para("Problem addressed: "+row["problem"]),
              para("Transformation",h2),para(f"Move from a vague or reactive approach to {title.lower()} toward a visible decision model that can be tested, reviewed, and turned into a repeatable practice.",quote),
              para("Core framework",h2),para(f"{title} Operating Loop: OBSERVE -> SEPARATE -> CHOOSE -> TEST -> REVIEW -> STANDARDIZE",quote),PageBreak()]
    story += [para("Introduction",h1),
              para(f"{title} sits inside {domain.lower()}. {row['thesis']}"),
              para(f"The practical problem is not a shortage of opinions. It is that {row['problem']}. This book therefore treats knowledge as a tool for making choices, not as a substitute for making them."),
              para("Three habits run through the book: make the situation concrete, name the trade-off, and define what would change your mind. Those habits keep useful frameworks grounded when conditions are messy."),
              para("Examples in this edition are constructed scenarios unless explicitly identified otherwise. Psychological ideas are used as explanatory lenses; no fabricated studies, statistics, testimonials, endorsements, or guaranteed outcomes are used."),
              PageBreak()]
    for ci,ch in enumerate(CHAPTERS[domain]):
        story.append(para(f"Chapter {ci+1}: {ch}",h1))
        for x in chapter_copy(row,ch,ci): story.append(para(x))
        story.append(para("Chapter check: What is the trigger? What is fixed? What can move? What is the downside? What evidence would justify changing the rule?",small))
        story.append(PageBreak() if ci<7 else Spacer(1,4))
    story += [PageBreak(),para("Constructed Case Studies",h1)]
    for n,scenario in enumerate([
        f"Mira is a fictional operator dealing with {row['problem']}. She applies the core loop to a single real case, discovers that the visible problem is downstream of an earlier choice, and changes the trigger instead of merely adding more effort.",
        f"Arin has two plausible paths. He writes the trade-offs explicitly, identifies which step is reversible, and runs the smaller test first. The result is useful even if the test fails because it reduces uncertainty without committing the whole project.",
        f"Noor is skilled but inconsistent. She moves the framework out of her head and into a simple checklist with a review point. The system becomes easier to run on ordinary days and easier to repair after a miss."
    ],1):
        story += [para(f"Case {n}",h2),para(scenario),para("Lesson: the value is in making the decision inspectable. A good system makes mistakes visible early enough to correct them.")]

    story += [PageBreak(),para("Cheat Codes",h1)]
    for i,code in enumerate([
        "Decision rule: define the desired outcome before choosing the tactic.",
        "Shortcut: prefer a small reversible move when the evidence is weak.",
        "Question: what does this choice make harder to do later?",
        "Heuristic: recurring work is a candidate for a default, template, checklist, or automation.",
        "Mistake rule: visible activity is not proof of useful progress.",
        "Review rule: write the condition that would make you change the current approach.",
        "Quality rule: add a check where an error becomes expensive, not only after the error happens.",
        "Execution rule: define 'done' before starting."
    ],1): story.append(para(f"{i:02d}. {code}"))
    story += [para("Power Principle",h2),para("Structure often beats intention. Incentives, constraints, timing, information, defaults, and boundaries influence behavior. Use this as an analytical lens for the situation, not as a trick for controlling people."),PageBreak()]

    story += [para("Common Mistakes",h1)]
    for x in [
        "Trying to solve the largest version of the problem before understanding the smallest repeatable version.",
        "Adding tools before defining the outcome the tools are supposed to improve.",
        "Using a framework as a rigid script instead of adapting it to context.",
        "Ignoring trade-offs because the upside sounds attractive.",
        "Failing to record what happened, which prevents the system from learning."
    ]: story.append(para(x))
    story += [para("Advanced Insights",h2),
              para("The advanced move is integration: connect the central idea to incentives, timing, quality control, ownership, distribution, and review. The strongest leverage point is often the handoff between two systems."),
              para("What Nobody Tells Beginners",h2),
              para("Knowing the right sentence is not the same as building the right process. Real progress comes from making the right question appear at the right moment and noticing when the answer has stopped working."),
              PageBreak()]

    story += [para("Exercises",h1)]
    for i,x in enumerate([
        "Describe one current situation in facts only. Put interpretation in a separate line.",
        "Run the core framework against a real decision from this month.",
        "Find one recurring cost created by a missing default.",
        "Design one reversible experiment and define the signal that counts as useful.",
        "Write one rule to keep, one to test, and one to retire."
    ],1): story.append(para(f"{i}. {x}"))
    story += [PageBreak(),para("7-Day Implementation Plan",h1)]
    for x in [
        "Day 1 - Observe the real situation and capture examples.",
        "Day 2 - Write the outcome, constraint, and current decision.",
        "Day 3 - Apply the core framework to one concrete case.",
        "Day 4 - Remove one source of friction or ambiguity.",
        "Day 5 - Run the smallest useful experiment.",
        "Day 6 - Review the signal and record what surprised you.",
        "Day 7 - Convert the strongest learning into one default rule."
    ]: story.append(para(x))
    story += [para("30-Day Implementation Plan",h1)]
    for x in ["Week 1 - Baseline and observation.","Week 2 - Repeat the framework and adjust the environment.","Week 3 - Review time, quality, risk, reliability, or decision clarity.","Week 4 - Keep what works, remove what does not, and document the new default."]: story.append(para(x))
    story += [PageBreak(),para("One-Page Cheat Sheet",h1),para("Central thesis",h2),para(row["thesis"],quote),para("Core loop",h2),para("OBSERVE -> SEPARATE -> CHOOSE -> TEST -> REVIEW -> STANDARDIZE",quote),para("Five questions",h2)]
    for x in ["What is the actual outcome?","What constraint matters most?","What is the smallest reversible move?","What evidence would change my mind?","What should become a default if this works?"]: story.append(para(x))
    story += [para("Five rules",h2)]
    for x in ["Make the problem visible.","Name the trade-off.","Protect the downside.","Test before scaling.","Record what you learn."]: story.append(para(x))
    story += [PageBreak(),para("Conclusion",h1),para(f"The practical value of {title} is not in finishing a PDF. It is in having a clearer way to approach {row['problem']}. Keep the framework close to the work, use it when the decision is real, and improve it from evidence."),para("This book is one component of the EBOOX progression. It is useful alone, and it becomes more useful when its ideas connect with neighboring skills in the collection.")]

    story += [NextPageTemplate("back"),PageBreak(),Cover(title,f"{row['thesis']}\\n\\nCore domain: {domain}.\\n\\nEBOOX 100 is an independently created digital library for practical thinking, building, selling, leading, and long-term leverage.",True,accent,num,domain)]
    doc.build(story)
    return path



SHORT_PUNCH={"Money Psychology":"Make better money decisions. Keep more options.","AI Money":"Compress work without lowering judgment.","Business Strategy":"Stop doing everything. Build the advantage that matters.","Sales & Negotiation":"Sell value. Trade variables. Protect trust.","Marketing & Attention":"Attention is rented. Meaning is the asset.","Entrepreneurship & Opportunity":"Find friction people already pay to escape.","Discipline & Self-Mastery":"Make execution easier than avoidance.","Digital Products & Creator Business":"Turn useful knowledge into assets people can use.","Power, Leadership & Social Intelligence":"Read the room. Set the frame. Keep trust.","Future Skills & Long-Term Leverage":"Build skills that get stronger as tools change."}

def draw_rule(c,x1,y,x2,color,lw=1):
    c.setStrokeColor(colors.HexColor(color)); c.setLineWidth(lw); c.line(x1,y,x2,y)

def draw_para(c,text,x,y_top,width,style):
    p=Paragraph(esc(text),style); w,h=p.wrap(width,1000); p.drawOn(c,x,y_top-h); return h

def wrap_lines(c,text,font,size,maxw):
    words=str(text).split(); lines=[]; cur=""
    for word in words:
        trial=(cur+" "+word).strip()
        if stringWidth(trial,font,size)<=maxw: cur=trial
        else:
            if cur: lines.append(cur)
            cur=word
    if cur: lines.append(cur)
    return lines

def ornament(c,W,H,accent,deep):
    m=28; c.setStrokeColor(colors.HexColor(accent)); c.setLineWidth(.9); c.rect(m,m,W-2*m,H-2*m,fill=0,stroke=1)
    c.setStrokeColor(colors.HexColor("#6D604A")); c.rect(m+7,m+7,W-2*(m+7),H-2*(m+7),fill=0,stroke=1)
    for sx,sy in [(1,1),(1,-1),(-1,1),(-1,-1)]:
        x=m+12 if sx==1 else W-m-12; y=m+12 if sy==1 else H-m-12
        c.circle(x,y,5,fill=0,stroke=1); c.line(x,y,x+sx*25,y); c.line(x,y,x,y+sy*25)

def page_header(c,W,H,domain,title,chapter,idx,accent):
    c.setFillColor(colors.HexColor("#F4EFE6")); c.rect(0,0,W,H,fill=1,stroke=0)
    c.saveState(); c.setStrokeColor(colors.HexColor("#E7DECF")); c.setLineWidth(.35)
    for x in range(int(-H),int(W),22): c.line(x,0,x+H,H)
    c.restoreState()
    draw_rule(c,44,H-45,W-44,accent,1.2)
    c.setFillColor(colors.HexColor(accent)); c.setFont("Helvetica-Bold",7.5); c.drawString(44,H-32,domain.upper())
    c.setFillColor(colors.HexColor("#77736B")); c.setFont("Helvetica",7); c.drawRightString(W-44,H-32,f"CHAPTER {chapter}  /  {idx:02d}")
    c.setFillColor(colors.HexColor("#B8A37B")); c.setFont("Helvetica",7); c.drawString(44,24,title.upper()); c.drawRightString(W-44,24,str(idx))

def page_title(c,W,H,kicker,title,accent):
    c.setFillColor(colors.HexColor(accent)); c.setFont("Helvetica-Bold",7.3); c.drawString(54,H-92,kicker.upper())
    c.setFillColor(colors.HexColor("#1B1A18")); c.setFont("Times-Bold",24)
    lines=wrap_lines(c,title,"Times-Bold",24,W-108); y=H-127
    for line in lines[:2]: c.drawString(54,y,line); y-=27
    draw_rule(c,54,y+7,W-54,accent,.8)

def content_block(c,x,y,w,h,title,body,accent,fill="#F8F3EA"):
    c.setFillColor(colors.HexColor(fill)); c.roundRect(x,y-h,w,h,8,fill=1,stroke=0)
    c.setStrokeColor(colors.HexColor("#D4C8B5")); c.setLineWidth(.6); c.roundRect(x,y-h,w,h,8,fill=0,stroke=1)
    c.setFillColor(colors.HexColor(accent)); c.setFont("Helvetica-Bold",8); c.drawString(x+13,y-20,title.upper())
    draw_para(c,body,x+13,y-30,w-26,BODY_SMALL)

